BASE_URL = "https://pgsindia-ncof.gov.in"

NAV_TIMEOUT = 30_000
ACTION_TIMEOUT = 15_000

LOG_FIELDS = ["no", "farmer", "offered_for_organic", "area_shown", "expected_yield", "self_consumption",
              "status", "detail", "timestamp"]
EXCEL_HEADERS = ["No.", "Farmer", "Offered for organic (ha)", "Area shown (ha)", "Expected yield (qt)",
                 "Self consumption (qt)", "Status", "Detail", "Time"]

# the label printed above each field on the "Add Peers Appraisal" page  ->  kind of control under it
FIELD_LABELS = {
    "farmer": ("Farmer", "select"),
    "category": ("Crop Category", "select"),
    "crop": ("Crop", "select"),
    "offered": ("Offered for organic", "input"),
    "area": ("Area Shown in (Ha)", "input"),
    "yield": ("Expected Yields in (Quintals)", "input"),
    "self": ("Self Consumption in (Quintals)", "input"),
}
_UP, _LOW = "ABCDEFGHIJKLMNOPQRSTUVWXYZ", "abcdefghijklmnopqrstuvwxyz"


def norm(text: str) -> str:
    return re.sub(r"\s+", " ", str(text or "")).strip().lower()


def to_num(text):
    return float(str(text).replace(",", "").strip())


def fmt_num(x: float) -> str:
    return str(int(x)) if float(x).is_integer() else str(x)


@dataclass
class Config:
    out_dir: str
    category: str = "CEREALS"
    crop: str = "PADDY (DHAN)"
    # (offered for organic, area shown, expected yield, self consumption) - all in the portal's units
    rules: tuple = (("2", "2", "6", "5"), ("1", "1", "3", "3"))
    start_at: int = 1           # start at this farmer number of the dropdown list
    max_count: int = 0          # 0 = all farmers
    test_mode: bool = False     # fill the first farmer but do NOT press ADD
    slow_mo: int = 100
    base_url: str = BASE_URL
    browser_channel: str = ""   # "", "msedge", "chrome" or "chromium" (preferred first)


class FatalError(Exception):
    """Stops the whole run (browser closed...)."""


def find_rule(cfg: Config, offered: float):
    for r in cfg.rules:
        try:
            if abs(to_num(r[0]) - offered) < 1e-6:
                return r
        except ValueError:
            continue
    return None


def pick_option(options, wanted):
    """options = [(value, text)]. Exact text first, then 'contains', then the only option with the first word."""
    w = norm(wanted)
    if not w:
        return None
    for v, t in options:
        if norm(t) == w:
            return v, t
    contains = [(v, t) for v, t in options if w in norm(t)]
    if len(contains) == 1:
        return contains[0]
    first = w.replace("(", " ").replace(")", " ").split()[0]
    loose = [(v, t) for v, t in options if first in norm(t) and norm(t) not in ("--select--", "select")]
    if len(loose) == 1:
        return loose[0]
    return None


# ───────────────────────────── result files ─────────────────────────────

def new_run_files(out_dir: str):
    stamp = f"{datetime.now():%Y-%m-%d_%H-%M-%S}"
    d = Path(out_dir)
    d.mkdir(parents=True, exist_ok=True)
    return d / f"farmers_added_{stamp}.csv", d / f"farmers_added_{stamp}.xlsx"


def append_csv(path: Path, row: dict):
    new = not path.exists()
    with open(path, "a", newline="", encoding="utf-8-sig") as f:
        w = csv.DictWriter(f, fieldnames=LOG_FIELDS, extrasaction="ignore")
        if new:
            w.writeheader()
        w.writerow(row)


def write_excel(path: Path, rows: list):
    from openpyxl.styles import Alignment, Font, PatternFill
    if not rows:
        return None
    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = "Farmers added"
    ws.append(EXCEL_HEADERS)
    for c in ws[1]:
        c.font = Font(bold=True, color="FFFFFF")
        c.fill = PatternFill("solid", fgColor="1F6F43")
        c.alignment = Alignment(horizontal="center", vertical="center", wrap_text=True)
    for r in rows:
        ws.append([int(r["no"]), r["farmer"], r["offered_for_organic"], r["area_shown"], r["expected_yield"],
                   r["self_consumption"], r["status"], r["detail"], r["timestamp"]])
    colours = {"Added": "E2F4E8", "Skipped": "FFF4D6", "Failed": "FBE0E0", "Test": "E3EEFB"}
    for row in ws.iter_rows(min_row=2):
        fill = colours.get(row[6].value)
        if fill:
            for c in row:
                c.fill = PatternFill("solid", fgColor=fill)
    for col, w in zip("ABCDEFGHI", (7, 48, 14, 12, 14, 14, 11, 60, 20)):
        ws.column_dimensions[col].width = w
    ws.freeze_panes = "A2"
    wb.save(path)
    return path


# ───────────────────────────── the page ─────────────────────────────

def _label_xpath(text: str) -> str:
    """Any element whose own text is exactly this label (ignoring *, ':' and upper/lower case)."""
    return (f"//*[./text()[translate(normalize-space(translate(., '*:', '')), '{_UP}', '{_LOW}')"
            f"='{text.lower()}']]")


class Runner:
    def __init__(self, cfg: Config, emit, stop_event, login_event, pause_event=None, close_event=None, cmd_q=None):
        self.cfg = cfg
        self.emit = emit
        self.stop = stop_event
        self.login_event = login_event
        self.pause = pause_event            # set = paused (takes effect between farmers)
        self.close_event = close_event      # set = close the browser when the farmers are done
        self.cmd_q = cmd_q                  # jobs for the compliance page: ("compliance", {...}) / ("status_options",)
        self.dialog_msgs = []
        self.rows = []
        self.csv_path = None
        self.xlsx_path = None

    # -- helpers --
    def log(self, msg, level="info"):
        self.emit(("log", level, msg))

    async def _on_dialog(self, dialog):
        self.dialog_msgs.append(dialog.message)
        self.log(f"   portal message: {dialog.message!r} -> OK")
        await dialog.accept()

    def _watch(self, page):
        page.on("dialog", self._on_dialog)

    async def launch(self, pw):
        """Use the PC's own Edge/Chrome first; fall back to the downloaded Chromium."""
        order = []
        for ch in (self.cfg.browser_channel, "msedge", "chrome", "chromium"):
            if ch != "" and ch not in order:
                order.append(ch)
        if not order:
            order = ["msedge", "chrome", "chromium"]
        errors = []
        for ch in order:
            try:
                kwargs = dict(headless=False, slow_mo=self.cfg.slow_mo, args=["--start-maximized"])
                if ch != "chromium":
                    kwargs["channel"] = ch
                browser = await pw.chromium.launch(**kwargs)
                self.log(f"Browser started ({ch}).")
                return browser
            except Exception as e:
                errors.append(f"{ch}: {str(e).strip().splitlines()[0] if str(e).strip() else 'failed'}")
        raise FatalError(
            "Could not start a browser. Open the launcher and click 'Install Required Software'.\n"
            + "\n".join(errors)
        )

    async def debug_dump(self, page, tag):
        """Save what the page looked like when something unexpected happened."""
        d = Path(self.cfg.out_dir) / "debug"
        d.mkdir(parents=True, exist_ok=True)
        base = d / f"{datetime.now():%Y%m%d_%H%M%S}_{re.sub(r'[^A-Za-z0-9_-]+', '_', tag)[:50]}"
        lines = []
        try:
            lines.append(f"URL: {page.url}")
            lines.append(f"TITLE: {await page.title()}")
            lines.append(f"OPEN TABS: {len(page.context.pages)}")
        except Exception as e:
            lines.append(f"(page info failed: {e})")
        try:
            txt = await page.inner_text("body", timeout=3_000)
            lines += ["", "--- visible text, first 4000 chars ---", txt[:4000]]
        except Exception:
            pass
        try:
            html = await page.evaluate(
                "() => { const f = document.querySelector('form') || document.body; return f.outerHTML; }")
            base.with_suffix(".html").write_text(html[:400_000], encoding="utf-8")
        except Exception:
            pass
        try:
            base.with_suffix(".txt").write_text("\n".join(lines), encoding="utf-8")
        except Exception:
            pass
        try:
            await page.screenshot(path=str(base.with_suffix(".png")), full_page=True)
        except Exception:
            pass
        return base.with_suffix(".txt")

    async def screenshot(self, page, name):
        d = Path(self.cfg.out_dir) / "screenshots"
        d.mkdir(parents=True, exist_ok=True)
        safe = re.sub(r"[^\w\-]+", "_", name)[:60]
        path = d / f"{datetime.now():%Y%m%d_%H%M%S}_{safe}.png"
        await page.screenshot(path=str(path), full_page=True)
        return path

    async def _visible_first(self, loc):
        n = await loc.count()
        for i in range(n):
            el = loc.nth(i)
            try:
                if await el.is_visible():
                    return el
            except Exception:
                continue
        return None

    async def fields(self, page):
        """Locate the seven controls of the 'add farmer' block. Returns {name: locator}; missing ones are left out."""
        found = {}
        for key, (text, tag) in FIELD_LABELS.items():
            nxt = "select" if tag == "select" else "input[not(@type='hidden')]"
            loc = page.locator(f"xpath=({_label_xpath(text)}/following::{nxt}[1])")
            el = await self._visible_first(loc)
            if el is not None:
                found[key] = el
        return found

    async def find_form_page(self, context):
        for page in reversed(context.pages):
            if page.is_closed():
                continue
            try:
                f = await self.fields(page)
            except Exception:
                continue
            if len(f) == len(FIELD_LABELS):
                return page, f
        return None, {}

    @staticmethod
    async def read_options(sel):
        return [tuple(o) for o in await sel.evaluate(
            "s => [...s.options].map(o => [o.value, (o.textContent || '').replace(/\\s+/g, ' ').trim()])")]

    @staticmethod
    async def selected_text(sel):
        return await sel.evaluate(
            "s => s.selectedIndex < 0 ? '' : (s.options[s.selectedIndex].textContent || '').replace(/\\s+/g, ' ').trim()")

    async def choose(self, sel, opt):
        v, t = opt
        if v != "":
            await sel.select_option(value=v, timeout=ACTION_TIMEOUT)
        else:
            await sel.select_option(label=t, timeout=ACTION_TIMEOUT)

    async def wait_option(self, sel, wanted, timeout=12.0):
        """The options of Crop Category / Crop are loaded by the portal after the previous choice."""
        end = time.time() + timeout
        last = []
        while time.time() < end:
            last = await self.read_options(sel)
            opt = pick_option([o for o in last if not norm(o[1]).startswith("--")], wanted)
            if opt:
                return opt, last
            await asyncio.sleep(0.4)
        return None, last

    async def stable_value(self, loc, timeout=10.0, settle=0.9):
        """Read an input once the portal has finished filling it in (non-empty and unchanged for `settle` s)."""
        end = time.time() + timeout
        t0 = time.time()
        prev, since = None, time.time()
        while time.time() < end:
            v = (await loc.input_value()).strip()
            if v != prev:
                prev, since = v, time.time()
            if v and time.time() - since >= settle and time.time() - t0 >= settle:
                return v
            await asyncio.sleep(0.2)
        return prev or ""

    async def add_button(self, f):
        xp = ("xpath=following::*[(self::button or self::a or self::input or self::span) and "
              "(normalize-space(.)='ADD' or normalize-space(.)='Add' or @value='ADD' or @value='Add')][1]")
        el = await self._visible_first(f["self"].locator(xp))
        if el is None:
            raise FatalError("The ADD button was not found on the page (it should be next to the Self "
                             "Consumption field).")
        return el

    async def row_count(self, page):
        return await page.evaluate(
            "() => [...document.querySelectorAll('tr')].filter(r => r.offsetParent !== null).length")

    # -- one farmer --
    async def add_farmer(self, page, f, value, text):
        """Returns (status, offered, area, yield, self, detail). status: Added / Skipped / Failed / Test."""
        cfg = self.cfg
        blank = ("", "", "", "")
        options = await self.read_options(f["farmer"])
        farmer_opt = None
        for v, t in options:
            if (value != "" and v == value) or (value == "" and t == text):
                farmer_opt = (v, t)
                break
        if farmer_opt is None:
            return ("Skipped",) + blank + ("not in the Farmer list any more (already added?)",)

        offered = None
        for attempt in (1, 2):
            await self.choose(f["farmer"], farmer_opt)
            await asyncio.sleep(0.9)                                  # portal loads the farmer's crop categories
            cat, cat_opts = await self.wait_option(f["category"], cfg.category)
            if not cat:
                names = ", ".join(t for _, t in cat_opts if not norm(t).startswith("--")) or "none"
                return ("Failed",) + blank + (f"crop category {cfg.category!r} is not available for this farmer "
                                              f"(available: {names})",)
            await self.choose(f["category"], cat)
            await asyncio.sleep(0.9)                                  # portal loads the crops
            crop, crop_opts = await self.wait_option(f["crop"], cfg.crop)
            if not crop:
                names = ", ".join(t for _, t in crop_opts if not norm(t).startswith("--")) or "none"
                return ("Failed",) + blank + (f"crop {cfg.crop!r} is not available (available: {names})",)
            await self.choose(f["crop"], crop)
            raw = await self.stable_value(f["offered"])
            ok_sel = (norm(await self.selected_text(f["farmer"])) == norm(farmer_opt[1])
                      and norm(await self.selected_text(f["category"])) == norm(cat[1])
                      and norm(await self.selected_text(f["crop"])) == norm(crop[1]))
            try:
                offered = to_num(raw)
            except ValueError:
                offered = None
            if ok_sel and offered is not None:
                break
            if attempt == 1:
                self.log("   page was still reloading - trying this farmer once more", "warn")
                await asyncio.sleep(1.5)
                continue
            if not ok_sel:
                return ("Failed",) + blank + ("the portal changed a dropdown while selecting - nothing was added",)
            return ("Failed",) + blank + (f"could not read 'Offered for organic' (found {raw!r})",)

        rule = find_rule(cfg, offered)
        shown = fmt_num(offered)
        if rule is None:
            return ("Skipped", shown, "", "", "", f"no rule for offered area {shown} ha - fill this farmer by hand")
        _, area, yld, own = rule
        for key, val in (("area", area), ("yield", yld), ("self", own)):
            await f[key].fill(val, timeout=ACTION_TIMEOUT)
        got = [(await f[k].input_value()).strip() for k in ("area", "yield", "self")]
        if [to_num(x) for x in got if x] != [to_num(area), to_num(yld), to_num(own)] or "" in got:
            return ("Failed", shown, area, yld, own, f"the numbers did not stay in the boxes (read back {got})")

        if cfg.test_mode:
            return ("Test", shown, area, yld, own, "test mode - ADD was NOT pressed")

        btn = await self.add_button(f)
        rows_before = await self.row_count(page)
        dialogs_before = len(self.dialog_msgs)
        await btn.scroll_into_view_if_needed(timeout=ACTION_TIMEOUT)
        await btn.click(timeout=ACTION_TIMEOUT)
        end = time.time() + 8
        while time.time() < end:
            await asyncio.sleep(0.4)
            if len(self.dialog_msgs) > dialogs_before:
                msg = " / ".join(self.dialog_msgs[dialogs_before:])
                if re.search(r"success|added|saved", msg, re.I) and not re.search(r"not|invalid|error|fail|already", msg, re.I):
                    return ("Added", shown, area, yld, own, msg[:120])
                return ("Failed", shown, area, yld, own, f"portal said: {msg[:200]}")
            if page.is_closed():
                raise FatalError("The browser window was closed.")
            gone = not any(v == farmer_opt[0] and t == farmer_opt[1] for v, t in await self.read_options(f["farmer"]))
            reset = norm(await self.selected_text(f["farmer"])).startswith("--") or (await f["area"].input_value()).strip() == ""
            if gone or reset or await self.row_count(page) > rows_before:
                return ("Added", shown, area, yld, own, "")
        return ("Failed", shown, area, yld, own, "pressing ADD had no visible effect (nothing was added)")

    # -- compliance page (after Save & Next) --
    async def find_page_with(self, context, js_test):
        for page in reversed(context.pages):
            if page.is_closed():
                continue
            try:
                if await page.evaluate(js_test):
                    return page
            except Exception:
                continue
        return None

    async def process_commands(self, context):
        if self.cmd_q is None:
            return
        while True:
            try:
                cmd = self.cmd_q.get_nowait()
            except queue.Empty:
                return
            try:
                if cmd[0] == "compliance":
                    await self.do_compliance(context, cmd[1])
                elif cmd[0] == "status_options":
                    await self.read_status_options(context)
            except FatalError:
                raise
            except Exception as exc:
                self.log("   FAILED: " + ((str(exc).strip().splitlines() or [repr(exc)])[0][:220]), "err")
            finally:
                self.emit(("cmd_done", cmd[0]))

    _FIND_CLAUSES = "() => /standard clause/i.test(document.body.innerText)"
    _FIND_MEMBERS = "() => /recommended status/i.test(document.body.innerText)"

    _JS_RADIOS = r"""(wanted) => {
        const norm = s => (s || '').replace(/\s+/g, ' ').trim().toLowerCase();
        const all = [...document.querySelectorAll('input[type=radio]')];
        const tables = [...document.querySelectorAll('table')].filter(t => /standard clause/i.test(t.innerText || ''));
        tables.sort((a, b) => (a.textContent || '').length - (b.textContent || '').length);
        const scope = tables[0] || null;
        const labelOf = r => {
            let t = '';
            if (r.labels && r.labels.length) t = r.labels[0].innerText;
            if (!norm(t) && r.closest('label')) t = r.closest('label').innerText;
            if (!norm(t)) { let n = r.nextSibling; while (n && !norm(t)) { t = n.textContent; n = n.nextSibling; } }
            if (!norm(t) && r.nextElementSibling) t = r.nextElementSibling.innerText;
            t = norm(t);
            if (!t) { const v = norm(r.value); if (['yes', 'y'].includes(v)) t = 'yes'; if (['no', 'n'].includes(v)) t = 'no'; }
            return t;
        };
        const groups = new Map();
        all.forEach((r, i) => {
            if (scope && !scope.contains(r)) return;
            const key = r.name || ('row' + (r.closest('tr') ? [...document.querySelectorAll('tr')].indexOf(r.closest('tr')) : i));
            if (!groups.has(key)) groups.set(key, []);
            groups.get(key).push([i, labelOf(r)]);
        });
        const pick = [], bad = [];
        groups.forEach((items, key) => {
            const hit = items.find(x => x[1] === wanted);
            if (hit) pick.push(hit[0]); else bad.push(key + ': ' + items.map(x => x[1] || '?').join('/'));
        });
        return {pick, bad, groups: groups.size, scoped: !!scope};
    }"""

    _JS_MEMBER_SELECTS = r"""() => {
        const all = [...document.querySelectorAll('select')];
        const tables = [...document.querySelectorAll('table')].filter(t => /recommended status/i.test(t.innerText || ''));
        tables.sort((a, b) => (a.textContent || '').length - (b.textContent || '').length);
        const scope = tables[0] || null;
        const out = [];
        all.forEach((s, i) => {
            if (scope && !scope.contains(s)) return;
            const tr = s.closest('tr');
            let name = '';
            if (tr) { const cells = [...tr.children].map(c => (c.innerText || '').trim()).filter(x => x); name = cells.length > 1 ? cells[1] : (cells[0] || ''); }
            out.push({i, name, options: [...s.options].map(o => [o.value, (o.textContent || '').replace(/\s+/g, ' ').trim()])});
        });
        return {selects: out, scoped: !!scope};
    }"""

    @staticmethod
    def _key(text):
        return re.sub(r"[^a-z0-9]+", "", str(text or "").lower())

    def _match_status(self, options, wanted):
        k = self._key(wanted)
        real = [(v, t) for v, t in options if not norm(t).startswith("--") and norm(t) not in ("", "select")]
        for v, t in real:
            if self._key(t) == k:
                return v, t
        cont = [(v, t) for v, t in real if k and k in self._key(t)]
        return cont[0] if len(cont) == 1 else None

    async def do_compliance(self, context, job):
        answer = str(job.get("answer", "Yes")).strip().lower()
        status = str(job.get("status", "")).strip()
        self.log(f"=== Compliance page: answer \"{answer.title()}\" for every clause, recommended status "
                 f"\"{status}\" for every member ===", "head")
        page = await self.find_page_with(context, self._FIND_CLAUSES)
        if page is None:
            page = await self.find_page_with(context, self._FIND_MEMBERS)
        if page is None:
            tab = context.pages[-1] if context.pages else None
            if tab is not None:
                dump = await self.debug_dump(tab, "compliance_page_not_found")
                self.log(f"   (page details saved in {dump})", "warn")
            self.log("The compliance page was not found. In the browser, click Save & Next so the page with "
                     "'Standard Clause' appears, then click this button again.", "err")
            return
        await page.bring_to_front()

        # 1 - Yes/No for every clause
        info = await page.evaluate(self._JS_RADIOS, answer)
        radios = page.locator("input[type=radio]")
        ok = 0
        for i in info["pick"]:
            r = radios.nth(i)
            got = await r.evaluate("e => { if (!e.checked) e.click(); return e.checked; }")
            ok += 1 if got else 0
        if not info["scoped"]:
            self.log("   (clause table not recognised - used every Yes/No group on the page)", "warn")
        if info["groups"] == 0:
            self.log("   No Yes/No clauses found on this page.", "warn")
        else:
            self.log(f"   Clauses answered {answer.title()}: {ok} of {info['groups']}", "ok" if ok == info["groups"] else "warn")
        for b in info["bad"][:5]:
            self.log(f"   could not answer: {b}", "warn")

        # 2 - recommended status for every member
        if not status:
            self.log("   No recommended status chosen - members left as they are.", "warn")
            return
        data = await page.evaluate(self._JS_MEMBER_SELECTS)
        selects = page.locator("select")
        done = bad = 0
        if not data["selects"]:
            dump = await self.debug_dump(page, "members_table_not_found")
            self.log(f"   The members table (Recommended Status) was not found. Details saved in {dump}", "err")
            return
        for item in data["selects"]:
            name = item["name"] or f"row {item['i']}"
            opt = self._match_status(item["options"], status)
            if opt is None:
                names = ", ".join(t for _, t in item["options"] if not norm(t).startswith("--")) or "none"
                self.log(f"   {name}: option {status!r} not available (choices: {names})", "err")
                bad += 1
                continue
            sel = selects.nth(item["i"])
            await self.choose(sel, opt)
            if norm(await self.selected_text(sel)) == norm(opt[1]):
                done += 1
            else:
                self.log(f"   {name}: the portal did not keep the choice", "err")
                bad += 1
            await asyncio.sleep(0.2)
        self.log(f"   Members set to \"{status}\": {done} of {len(data['selects'])}"
                 + (f"   (problems: {bad})" if bad else ""), "ok" if not bad else "warn")
        self.log("   Nothing was submitted - check the page, then click Submit yourself.", "head")

    async def read_status_options(self, context):
        page = await self.find_page_with(context, self._FIND_MEMBERS)
        if page is None:
            self.log("The members table was not found. Click Save & Next so the compliance page appears, then "
                     "click \"Load options from page\" again.", "err")
            return
        data = await page.evaluate(self._JS_MEMBER_SELECTS)
        names = []
        for item in data["selects"]:
            for _, t in item["options"]:
                if t and not norm(t).startswith("--") and t not in names:
                    names.append(t)
        if not names:
            self.log("No choices found in the Recommended Status boxes.", "err")
            return
        self.emit(("status_options", names))
        self.log("Recommended Status choices on this page: " + ", ".join(names), "ok")

    async def wait_for_ready(self, context):
        self.emit(("login",))
        while not self.login_event.is_set():
            if self.stop.is_set() or (self.close_event is not None and self.close_event.is_set()):
                return False
            await self.process_commands(context)
            await asyncio.sleep(0.3)
        self.login_event.clear()
        return True

    # -- main loop --
    async def run(self):
        cfg = self.cfg
        counts = {"added": 0, "skipped": 0, "failed": 0}
        self.csv_path, self.xlsx_path = new_run_files(cfg.out_dir)
        stopped = False
        try:
            async with async_playwright() as pw:
                browser = await self.launch(pw)
                try:
                    context = await browser.new_context(no_viewport=True)
                    context.on("page", self._watch)
                    main_page = await context.new_page()
                    try:
                        await main_page.goto(cfg.base_url, timeout=NAV_TIMEOUT, wait_until="domcontentloaded")
                    except Exception as e:
                        first = (str(e).strip().splitlines() or ["unknown error"])[0]
                        raise FatalError(f"Could not open the portal ({first[:120]}). "
                                         "Check your internet connection and try again.")
                    self.log("In the browser: log in, open Peers Appraisal > Add Peers Appraisal and fill in the "
                             "top part and the dates yourself.", "head")
                    self.log("Then click \"Ready - add farmers\" in this app.", "head")

                    page, f = None, {}
                    while page is None:
                        if not await self.wait_for_ready(context):
                            return counts, True          # closed before adding anything
                        page, f = await self.find_form_page(context)
                        if page is None:
                            tab = context.pages[-1] if context.pages else main_page
                            dump = await self.debug_dump(tab, "form_not_found")
                            self.log("The 'add farmer' block was not found. Open Add Peers Appraisal, scroll so the "
                                     "Farmer / Crop Category / Crop boxes are on the page, then click "
                                     "\"Ready - add farmers\" again.", "err")
                            self.log(f"   (page details saved in {dump})", "warn")
                    await page.bring_to_front()

                    options = [o for o in await self.read_options(f["farmer"])
                               if not norm(o[1]).startswith("--") and norm(o[1]) not in ("", "select")]
                    if not options:
                        raise FatalError("The Farmer dropdown is empty. Make sure the Season/Month/Year at the top "
                                         "are filled in, then try again.")
                    start = max(1, cfg.start_at)
                    todo = list(enumerate(options, start=1))[start - 1:]
                    if cfg.max_count:
                        todo = todo[:cfg.max_count]
                    if cfg.test_mode:
                        todo = todo[:1]
                    total = len(todo)
                    self.log(f"Farmer dropdown has {len(options)} farmer(s) - working on {total}"
                             + (" (TEST MODE - ADD will not be pressed)" if cfg.test_mode else "") + ".", "head")

                    for n, (idx, (value, text)) in enumerate(todo, start=1):
                        if self.pause is not None and self.pause.is_set() and not self.stop.is_set():
                            self.emit(("paused", True))
                            self.log("Paused - click Resume to continue. The browser stays open.", "warn")
                            while self.pause.is_set() and not self.stop.is_set():
                                await asyncio.sleep(0.3)
                            if not self.stop.is_set():
                                self.emit(("paused", False))
                                self.log("Resumed.", "ok")
                        if self.stop.is_set():
                            stopped = True
                            self.log("Stopped by user.", "warn")
                            break
                        ts = f"{datetime.now():%Y-%m-%d %H:%M:%S}"
                        self.log(f"[{n}/{total}] farmer {idx}: {text}", "head")
                        try:
                            f = await self.fields(page)
                            if len(f) < len(FIELD_LABELS):
                                missing = [k for k in FIELD_LABELS if k not in f]
                                raise FatalError("The page changed - these boxes are no longer on screen: "
                                                 + ", ".join(missing))
                            status, off, area, yld, own, detail = await self.add_farmer(page, f, value, text)
                        except FatalError:
                            raise
                        except Exception as exc:
                            if page.is_closed() or not browser.is_connected():
                                raise FatalError("The browser window was closed.")
                            status, off, area, yld, own = "Failed", "", "", "", ""
                            detail = (str(exc).strip().splitlines() or [repr(exc)])[0][:200]
                            try:
                                await self.screenshot(page, f"error_{idx}_{text}")
                            except Exception:
                                pass
                        level = {"Added": "ok", "Test": "ok", "Skipped": "warn", "Failed": "err"}[status]
                        shown = f"offered {off} ha -> area {area}, yield {yld}, self {own}" if area else (
                            f"offered {off} ha" if off else "")
                        self.log(f"   {status.upper()}  {shown}  {detail}".rstrip(), level)
                        row = {"no": idx, "farmer": text, "offered_for_organic": off, "area_shown": area,
                               "expected_yield": yld, "self_consumption": own, "status": status,
                               "detail": detail, "timestamp": ts}
                        self.rows.append(row)
                        append_csv(self.csv_path, row)
                        key = {"Added": "added", "Test": "added", "Skipped": "skipped", "Failed": "failed"}[status]
                        counts[key] += 1
                        self.emit(("progress", n, total, dict(counts)))

                    try:
                        if write_excel(self.xlsx_path, self.rows):
                            self.log(f"Excel file saved: {self.xlsx_path}", "ok")
                    except Exception as e:
                        self.log(f"Could not write the Excel file: {e}", "warn")
                    # the browser stays open so the user can check the list and press Save & Next themselves
                    self.emit(("added_all", counts, stopped, str(self.xlsx_path)))
                    while (not (self.close_event is not None and self.close_event.is_set())
                           and browser.is_connected() and any(not p.is_closed() for p in context.pages)):
                        await self.process_commands(context)
                        await asyncio.sleep(0.4)
                finally:
                    try:
                        await browser.close()
                    except Exception:
                        pass
        finally:
            try:
                if self.rows and not Path(self.xlsx_path).exists():
                    write_excel(self.xlsx_path, self.rows)
            except Exception:
                pass
        return counts, stopped



# ============================================================================
# REQUIREMENT CHECK / INSTALLER
# ============================================================================

APP_NAME = "PGS_Suspender"      # same data folder as the suspension tool, so the browser is shared
CHANNEL_LABELS = {"msedge": "Microsoft Edge", "chrome": "Google Chrome", "chromium": "Chromium (downloaded)"}


# ───────────────────────────── folders & settings ─────────────────────────────

def app_dir() -> Path:
    """Folder that holds the exe (or this script when run from source)."""
    if getattr(sys, "frozen", False):
        return Path(sys.executable).resolve().parent
    return Path(__file__).resolve().parent


def data_dir() -> Path:
    base = os.environ.get("LOCALAPPDATA") or str(Path.home() / ".local" / "share")
    d = Path(base) / APP_NAME
    d.mkdir(parents=True, exist_ok=True)
    return d


def browsers_dir() -> Path:
    return data_dir() / "browsers"


def default_output_dir() -> Path:
    return app_dir() / "PGS_Peers_Appraisal_Output"


def apply_env():
    """Tell Playwright where our downloaded browser lives. Call before using Playwright."""
    os.environ["PLAYWRIGHT_BROWSERS_PATH"] = str(browsers_dir())


def _settings_file() -> Path:
    return data_dir() / "settings.json"


def load_settings() -> dict:
    try:
        return json.loads(_settings_file().read_text(encoding="utf-8"))
    except Exception:
        return {}


def save_settings(**updates):
    data = load_settings()
    data.update(updates)
    try:
        _settings_file().write_text(json.dumps(data, indent=2), encoding="utf-8")
    except Exception:
        pass


# ───────────────────────────── detection ─────────────────────────────

def system_browsers() -> dict:
    """{'msedge': path, 'chrome': path} for the ones installed on this PC."""
    found = {}
    if sys.platform == "win32":
        bases = [os.environ.get(k) for k in ("PROGRAMFILES", "PROGRAMFILES(X86)", "LOCALAPPDATA")]
        rel = {
            "msedge": r"Microsoft\Edge\Application\msedge.exe",
            "chrome": r"Google\Chrome\Application\chrome.exe",
        }
        for ch, r in rel.items():
            for b in bases:
                if b and (Path(b) / r).exists():
                    found[ch] = str(Path(b) / r)
                    break
    else:  # only matters when running from source on mac/linux
        for ch, names in {"msedge": ("microsoft-edge", "microsoft-edge-stable"),
                          "chrome": ("google-chrome", "google-chrome-stable", "chrome")}.items():
            for n in names:
                p = shutil.which(n)
                if p:
                    found[ch] = p
                    break
    return found


def chromium_downloaded() -> bool:
    d = browsers_dir()
    return d.exists() and any(d.glob("chromium-*/INSTALLATION_COMPLETE"))


def quick_check() -> dict:
    """Fast check (no browser launch): {'ok': bool, 'channel': str, 'label': str}."""
    found = system_browsers()
    for ch in ("msedge", "chrome"):
        if ch in found:
            return {"ok": True, "channel": ch, "label": CHANNEL_LABELS[ch]}
    if chromium_downloaded():
        return {"ok": True, "channel": "chromium", "label": CHANNEL_LABELS["chromium"]}
    return {"ok": False, "channel": "", "label": ""}


# ───────────────────────────── installation ─────────────────────────────

def _driver_command():
    from playwright._impl._driver import compute_driver_executable
    res = compute_driver_executable()
    return list(res) if isinstance(res, (tuple, list)) else [str(res)]


def download_chromium(report) -> tuple:
    """Runs 'playwright install chromium'. Returns (ok, message)."""
    try:
        cmd = _driver_command() + ["install", "chromium"]
        try:
            from playwright._impl._driver import get_driver_env
            env = get_driver_env()
        except Exception:
            env = os.environ.copy()
        env["PLAYWRIGHT_BROWSERS_PATH"] = str(browsers_dir())
        flags = subprocess.CREATE_NO_WINDOW if sys.platform == "win32" else 0
        proc = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, env=env,
                                text=True, encoding="utf-8", errors="replace", creationflags=flags)
    except Exception as e:
        return False, f"Could not start the downloader: {e}"

    downloads, errors = 0, []
    for line in proc.stdout:
        line = line.strip()
        if not line:
            continue
        if line.startswith("Downloading"):
            downloads += 1
            report("log", re.sub(r"\s+from\s+https?://\S+", "", line))
        m = re.search(r"(\d{1,3})%", line)
        if m:
            frac = (max(downloads, 1) - 1 + min(int(m.group(1)), 100) / 100) / 3     # chromium + shell + ffmpeg
            report("progress", min(frac, 0.97))
        elif line.lower().startswith("error"):
            errors.append(line)
    rc = proc.wait()
    if rc == 0 and chromium_downloaded():
        report("progress", 1.0)
        return True, "Browser downloaded."
    detail = f" ({errors[0][:90]})" if errors else ""
    return False, ("Could not download the browser. Please check your internet connection "
                   "(some office or school networks block this download) and try again." + detail)


def test_browser() -> tuple:
    """Launch each available browser headlessly. Returns (channel or None, error text)."""
    async def _go():
        from playwright.async_api import async_playwright
        errors = []
        async with async_playwright() as pw:
            for ch in ("msedge", "chrome", "chromium"):
                try:
                    kw = {"headless": True}
                    if ch != "chromium":
                        kw["channel"] = ch
                    b = await pw.chromium.launch(**kw)
                    await b.close()
                    return ch, ""
                except Exception as e:
                    first = (str(e).strip().splitlines() or ["failed"])[0]
                    errors.append(f"{ch}: {first[:100]}")
        return None, "; ".join(errors)
    try:
        return asyncio.run(_go())
    except Exception as e:
        return None, str(e)[:200]


STEPS = ["Preparing folders", "Application engine", "Web browser", "Testing the browser"]


def run_setup(report) -> tuple:
    """
    Does the whole installation. `report` receives:
      ("step", index, "run"|"ok"|"fail", detail)   ("progress", 0..1 inside the browser step)   ("log", text)
    Returns (ok, message).
    """
    # 0. folders
    report("step", 0, "run", "")
    try:
        browsers_dir().mkdir(parents=True, exist_ok=True)
        default_output_dir().mkdir(parents=True, exist_ok=True)
    except Exception:
        pass                      # output folder next to the exe may be read-only; user can pick another
    report("step", 0, "ok", str(data_dir()))

    # 1. bundled engine
    report("step", 1, "run", "")
    try:
        import openpyxl      # noqa: F401
        import playwright.async_api  # noqa: F401
    except Exception as e:
        report("step", 1, "fail", str(e)[:80])
        return False, f"The application is missing a built-in component ({e}). Please re-download the tool."
    report("step", 1, "ok", "Built in")

    # 2. browser
    report("step", 2, "run", "")
    q = quick_check()
    if q["ok"]:
        report("step", 2, "ok", f"{q['label']} found")
    else:
        report("log", "No Edge/Chrome found - downloading Chromium (about 150 MB)...")
        ok, msg = download_chromium(report)
        if not ok:
            report("step", 2, "fail", "Download failed")
            return False, msg
        report("step", 2, "ok", "Chromium downloaded")

    # 3. prove it works
    report("step", 3, "run", "")
    channel, err = test_browser()
    if channel is None and not chromium_downloaded():
        report("log", "The installed browser could not be started - downloading Chromium instead...")
        report("step", 2, "run", "Downloading Chromium")
        ok, msg = download_chromium(report)
        if ok:
            report("step", 2, "ok", "Chromium downloaded")
            channel, err = test_browser()
        else:
            report("step", 2, "fail", "Download failed")
            report("step", 3, "fail", "Not tested")
            return False, msg
    if channel is None:
        report("step", 3, "fail", "Browser did not start")
        return False, f"A browser was found but could not be started. {err}"
    report("step", 3, "ok", f"{CHANNEL_LABELS[channel]} works")
    save_settings(requirements_ok=True, browser_channel=channel)
    return True, f"Everything is ready ({CHANNEL_LABELS[channel]})."



