# ───────────────────────────── dialogs ─────────────────────────────
class Dialog(ctk.CTkToplevel):
    """Small dark modal dialog. result = index of the clicked button (None if closed)."""

    def __init__(self, parent, title, message, buttons=("OK",), primary=0, tone="info"):
        super().__init__(parent)
        self.title(title)
        self.configure(fg_color=CARD)
        self.resizable(False, False)
        self.result = None
        accent = {"info": "#cfcfd6", "warn": AMBER, "error": RED, "ok": GREEN}.get(tone, "#cfcfd6")
        ctk.CTkFrame(self, height=3, fg_color=accent, corner_radius=0).pack(fill="x")
        label(self, title, 15, TEXT, "bold", anchor="w").pack(fill="x", padx=22, pady=(16, 4))
        label(self, message, 12, SOFT, justify="left", anchor="w", wraplength=430).pack(fill="x", padx=22, pady=(0, 16))
        row = ctk.CTkFrame(self, fg_color="transparent")
        row.pack(fill="x", padx=18, pady=(0, 16))
        for i in reversed(range(len(buttons))):
            button(row, buttons[i], lambda i=i: self._done(i), primary=(i == primary), width=110).pack(
                side="right", padx=4)
        self.protocol("WM_DELETE_WINDOW", lambda: self._done(None))
        self.bind("<Escape>", lambda e: self._done(None))
        self.update_idletasks()
        w, h = self.winfo_reqwidth(), self.winfo_reqheight()
        x = parent.winfo_rootx() + max(0, (parent.winfo_width() - w) // 2)
        y = parent.winfo_rooty() + max(0, (parent.winfo_height() - h) // 3)
        self.geometry(f"+{x}+{y}")
        try:
            self.transient(parent)
        except Exception:
            pass
        self.after(150, self._take_focus)

    def _take_focus(self):
        try:
            self.grab_set()
            self.focus_force()
        except tk.TclError:
            pass

    def _done(self, index):
        self.result = index
        try:
            self.grab_release()
        except tk.TclError:
            pass
        self.destroy()


def ask(parent, title, message, buttons=("OK",), primary=0, tone="info"):
    d = Dialog(parent, title, message, buttons, primary, tone)
    parent.wait_window(d)
    return d.result


# ───────────────────────────── launcher ─────────────────────────────
def _inside(card, event):
    w = card.winfo_containing(event.x_root, event.y_root)
    while w is not None:
        if w is card:
            return True
        w = getattr(w, "master", None)
    return False


def _bind_tree(widget, seq, fn):
    widget.bind(seq, fn, add="+")
    for child in widget.winfo_children():
        _bind_tree(child, seq, fn)


class ActionCard(ctk.CTkFrame):
    def __init__(self, parent, icon_b64, title, desc, command):
        super().__init__(parent, width=350, height=190, corner_radius=18, fg_color=CARD,
                         border_width=1, border_color="#33333a")
        self.grid_propagate(False)
        self.columnconfigure(0, weight=1)
        ctk.CTkLabel(self, text="", image=cimg(icon_b64, 44, 44)).grid(row=0, column=0, pady=(24, 6))
        head = ctk.CTkFrame(self, fg_color="transparent")
        head.grid(row=1, column=0, padx=16)
        label(head, title, 15, "#f4f4f6", "bold").pack(side="left")
        label(head, "   ›", 18, SOFT).pack(side="left")
        label(self, desc, 11, MUTED, justify="center", wraplength=290).grid(row=2, column=0, padx=16, pady=(6, 0))
        self._command = command
        _bind_tree(self, "<Button-1>", lambda e: self._command())
        _bind_tree(self, "<Enter>", lambda e: self.configure(border_color="#8a8a94", fg_color="#121216"))
        _bind_tree(self, "<Leave>", lambda e: None if _inside(self, e) else
                   self.configure(border_color="#33333a", fg_color=CARD))
        self.configure(cursor="hand2")


