class Spin(ctk.CTkFrame):
    def __init__(self, parent, var, lo=0, hi=10 ** 7, step=1, width=96):
        super().__init__(parent, fg_color="transparent")
        self.var, self.lo, self.hi, self.step = var, lo, hi, step
        entry(self, var, width=width - 26).grid(row=0, column=0, rowspan=2)
        for r, (txt, d) in enumerate((("▲", 1), ("▼", -1))):
            ctk.CTkButton(self, text=txt, width=22, height=16, corner_radius=4, font=F(7), fg_color="#1a1a1f",
                          hover_color="#2b2b32", text_color=SOFT,
                          command=lambda d=d: self._bump(d)).grid(row=r, column=1, padx=(4, 0), pady=(0, 2))

    def _bump(self, d):
        try:
            v = int(self.var.get())
        except ValueError:
            v = self.lo
        self.var.set(str(max(self.lo, min(self.hi, v + d * self.step))))


def checkbox(parent, text, var):
    return ctk.CTkCheckBox(parent, text=text, variable=var, checkbox_width=22, checkbox_height=22, corner_radius=6,
                           border_width=2, fg_color="#e9e9ee", hover_color="#ffffff", border_color="#4a4a52",
                           checkmark_color="#0b0b0d", text_color=TEXT, font=F(12))


